import { Box, Button, Card, CardHeader, Paper, Typography } from "@mui/material"
import { useWG } from "../WarGameContext";
import { WG_UNITS } from "../data/units";


export const WGControlPanel = ({ title }) => {
    const {credits, modelUnitSelected, setModelUnit} = useWG();
    return  <Paper sx={{ padding: 2, height: '100%' }}>
    <Typography variant="h6" gutterBottom>
      Panneau de controle
    </Typography>
    <Box>
        Credits: {credits} boules
    </Box>
    {WG_UNITS.map(unit=>(
        <Card sx={{marginTop:2, padding:1,border: modelUnitSelected===unit.type ? '2px solid rgba(237, 11, 11, 1)' : '1px solid #ccc'}}
        onClick={()=>setModelUnit(unit.type)}
         key={unit.type} >
            <CardHeader title={unit.name} subheader={<Typography variant="body2">Coût: {unit.cost} boules</Typography>}/>
                    <Box  sx={{marginTop:2, padding:1, border:'1px solid #ccc', borderRadius:1}}>
                        
                        <Typography variant="body2">Mouvement: {unit.movement}</Typography>
                        <Typography variant="body2">Attaque: {unit.attack}</Typography>
                        <Typography variant="body2">Défense: {unit.defense}</Typography>
                        <Typography variant="body2">Portée: {unit.range}</Typography>
                    </Box>

        </Card>
    ))}
    </Paper>
}