import React, { createContext, useContext, useEffect, useState } from "react";
import { WG_UNITS } from "./data/units";
import { generateHexGrid, placeEnemyUnitsOnMap } from "./hooks/hexUtils";

export const WarGameContext = createContext();

export const useWG = () => useContext(WarGameContext);
export function WarGameProvider({ children }) {
  const [credits, setCredits] = React.useState(1000);
  const [advUnits, setAdvUnits] = React.useState([]);
  const [userUnits, setUserUnits] = React.useState([]);
  const [grid, setGrid] = useState(new Map());
  const [modelUnitSelected, setModelUnit] = React.useState(null);
  const [unitSelected, setSelectedUnit] = React.useState(null);
  const [tileSelected, setTileSelected] = React.useState(null);
  const [explosionEffect, addExplosionEffect] = React.useState(null);

  const reset = () => {
    setCredits(1000);
    setAdvUnits([]);
    setUserUnits([]);
     const map = generateHexGrid(15);
    setGrid(map);

    const enemyUnits = placeEnemyUnitsOnMap(map, 5, WG_UNITS[0]);
    setAdvUnits(enemyUnits);
  }
  // ajoute unit a la carte
  const dropUnitModel = (tile) => {
    if (modelUnitSelected) {
      const unitClone = WG_UNITS.find(u => u.type === modelUnitSelected);
      if (!unitClone) {
        console.error("Modèle d'unité inconnu:", modelUnitSelected);
        return;
      }
      const unitID = crypto.randomUUID();
      setUserUnits([...userUnits, { ...unitClone, id: unitID, position: tile }]);
      setCredits(credits - unitClone.cost);
      setModelUnit(null);
      setSelectedUnit({ model: modelUnitSelected, position: tile });
    }
  }
  const attaque = (fromUnit, onUnit, attackerIsUser=true)=>{
    if(attackerIsUser){
      if(onUnit.damagePoints+fromUnit.attack>onUnit.defense){

        setAdvUnits(adv=>{
          addExplosionEffect(onUnit.position);
          return adv.filter(a=>a.id!==onUnit.id);
        })
      }
      else
        setAdvUnits(adv=>{
          return adv.map(a=>a.id===onUnit.id?{...a, damagePoints:a.damagePoints+fromUnit.attack}:a)
        })
    }
    else{
      //TODO
    }
    

  }

  // 3. Effet pour générer la carte au montage
  useEffect(() => {
   reset()
  }, []);

      // pour les explosions
      useEffect(() => {
          if (!explosionEffect) return;
          const timer = setTimeout(() => addExplosionEffect(null), 600);
          return () => clearTimeout(timer);
      }, [explosionEffect]);

  const contextValue = {
    credits,
    setCredits,
    reset,
    modelUnitSelected, setModelUnit, dropUnitModel
    , unitSelected, setSelectedUnit
    , advUnits, userUnits,setUserUnits, setAdvUnits
    , tileSelected, setTileSelected
    , grid, setGrid, attaque, explosionEffect
  }
  return (
    <WarGameContext.Provider value={contextValue}>
      {children}
    </WarGameContext.Provider>
  );
}