import React from 'react';
import {
  CssBaseline,
  AppBar,
  Toolbar,
  Typography,
  Box,
  Grid,
  Paper,
} from '@mui/material';
import HexBoard from './plateau/HexBoard';
import { WGControlPanel } from './panels/WGControlPanel';
import { WGSelectionPanel } from './panels/WGSelectionPanel';

// Composant simple pour les panneaux latéraux
const InfoPanel = ({ title }) => (
  <Paper sx={{ padding: 2, height: '100%' }}>
    <Typography variant="h6" gutterBottom>
      {title}
    </Typography>
    <Typography variant="body2">
      Contenu du panneau...
    </Typography>
  </Paper>
);

const GameLayout = () => {
  return (
    // Structure flex verticale pour remplir la vue
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <CssBaseline />
      
      {/* 1. Barre de titre */}
      <AppBar position="static">
        <Toolbar>
          <Typography variant="h6" component="div">
            Mon Wargame Hexagonal
          </Typography>
        </Toolbar>
      </AppBar>

      {/* 2. Zone de contenu principale (le reste de l'écran) */}
      <Box
        component="main"
        sx={{
          flexGrow: 1, // Prend toute la place restante
          padding: 2,
          overflow: 'hidden', // Empêche le débordement
          height: 'calc(100vh - 64px)' // Hauteur restante (viewport - appbar)
        }}
      >
        <Grid container spacing={2} sx={{ height: '100%' }}>
          
          {/* Colonne de gauche (Infos Unité) */}
          <Grid item xs={12} md={3} sx={{ height: { xs: 'auto', md: '100%' } }}>
            <WGSelectionPanel title="Infos selection" />
          </Grid>
          
          {/* Colonne centrale (Plateau de jeu) */}
          <Grid item xs={12} md={6} sx={{ height: { xs: '50vh', md: '100%' } }}>
            {/* Le Paper sert de conteneur pour le HexBoard */}
            <Paper sx={{ height: '100%', overflow: 'hidden' }}>
              <HexBoard/>
            </Paper>
          </Grid>
          
          {/* Colonne de droite (Actions) */}
          <Grid item xs={12} md={3} sx={{ height: { xs: 'auto', md: '100%' } }}>
            <WGControlPanel title="Actions" />
          </Grid>

        </Grid>
      </Box>
    </Box>
  );
};

export default GameLayout;