// src/HexBoard.jsx

import React, { useState, useEffect, useRef } from 'react';
import { Stage, Layer, RegularPolygon, Group, Image } from 'react-konva';
import { generateHexGrid, axialToPixel, HEX_SIZE, placeEnemyUnitsOnMap, hexDistance, getReachableTiles } from '../hooks/hexUtils';
import { useWG } from '../WarGameContext';
import { getHexagonPoints } from '../../civ/utils/hexUtils';
import { usePreloadedImages } from '../../civ/utils/hooks';
import { AllImageSources } from '../../civ/utils/imagesImports';
import { WG_UNITS } from '../data/units';


const SPRITE_SIZE = HEX_SIZE+5;
const HexBoard = () => {
  // 1. Référence au conteneur parent pour mesurer sa taille
  const containerRef = useRef(null);
  const { modelUnitSelected, setSelectedUnit,unitSelected, dropUnitModel, userUnits, advUnits
    , attaque, setTileSelected, grid, setUserUnits, explosionEffect
  } = useWG();
  const [stageSize, setStageSize] = useState({ width: 0, height: 0 });
const [reachableTiles, setReachableTiles] = useState([]);

  // 2. État pour notre carte (la grille logique)
  const images = usePreloadedImages(AllImageSources);

const handleClick = (hex) => {
  setTileSelected(hex);

  const foundUserUnit = userUnits.find(
    (u) => u.position.q === hex.q && u.position.r === hex.r
  );
  const foundAdvUnit = advUnits.find(
    (u) => u.position.q === hex.q && u.position.r === hex.r
  );

  // --- 1️⃣ Clic sur une unité alliée ---
  if (foundUserUnit) {
    setSelectedUnit(foundUserUnit);
    return;
  }

  // --- 2️⃣ Clic sur une tile vide ---
  if (!foundUserUnit && !foundAdvUnit) {
     if (modelUnitSelected)
      dropUnitModel(hex);
    else // Si une unité est sélectionnée, on envisage un déplacement
    if (unitSelected) {
      const dist = hexDistance(unitSelected.position, hex);
      if (dist <= unitSelected.movement) {
        // Déplacement autorisé
        setUserUnits((prev) =>
          prev.map((u) =>
            u.id === unitSelected.id ? { ...u, position: hex } : u
          )
        );
        setSelectedUnit(null); // optionnel : déselection après mouvement
      } else {
        // Trop loin, annule la sélection
        setSelectedUnit(null);
      }
    
    }
    return;
  }

  // --- 3️⃣ Clic sur une unité ennemie ---
  if (foundAdvUnit && unitSelected) {
    const dist = hexDistance(unitSelected.position, hex);
    if (dist <= unitSelected.range) {
      attaque(unitSelected,foundAdvUnit);
    } else {
      // Hors de portée
      setSelectedUnit(null);
    }
    return;
  }

  // --- 4️⃣ Clic sur une autre unité alliée (case occupée par une autre) ---
  if (foundUserUnit && unitSelected && foundUserUnit.id !== unitSelected.id) {
    setSelectedUnit(null);
    return;
  }

  // --- Cas par défaut ---
  setSelectedUnit(null);
};

  // 4. Effet pour mesurer le conteneur et mettre à jour la taille du Stage
  useEffect(() => {
    const checkSize = () => {
      if (containerRef.current) {
        setStageSize({
          width: containerRef.current.offsetWidth,
          height: containerRef.current.offsetHeight,
        });
      }
    };

    checkSize(); // Vérification initiale

    // On utilise un ResizeObserver pour détecter les changements de taille
    const resizeObserver = new ResizeObserver(checkSize);
    if (containerRef.current) {
      resizeObserver.observe(containerRef.current);
    }

    // Nettoyage au démontage
    return () => resizeObserver.disconnect();
  }, []); // Se lance une fois au montage

useEffect(() => {
  if (unitSelected && grid) {
    const tiles = getReachableTiles(unitSelected, grid);
    setReachableTiles(tiles);
  } else {
    setReachableTiles([]);
  }
}, [unitSelected, grid]);

  useEffect(()=>{
    if(unitSelected){
      // allume les cases disponible pour deplacement selon unitSelected.movement et terrain.movement

    }
  },[unitSelected])



  // 5. Calcul du centre du canvas pour centrer notre grille (0,0)
  const stageCenter = {
    x: stageSize.width / 2,
    y: stageSize.height / 2,
  };

  return (
    // Ce div est le conteneur que nous mesurons
    <div
      ref={containerRef}
      style={{ width: '100%', height: '100%', backgroundColor: '#eee' }}
    >
      <Stage width={stageSize.width} height={stageSize.height} draggable>
        {/* On décale le Layer pour que l'hex (0,0) soit au centre */}
        <Layer x={stageCenter.x} y={stageCenter.y}>
          {Array.from(grid.entries()).map(([key, hex]) => {
            // Calcule la position en pixels de cet hexagone
            const { x, y } = axialToPixel(hex.q, hex.r, HEX_SIZE);

            return (<Group
              key={key}
              x={x}
              y={y}
              clipFunc={(ctx) => {
                const points = getHexagonPoints(0, 0, HEX_SIZE);
                ctx.beginPath();
                ctx.moveTo(points[0].x, points[0].y);
                for (let i = 1; i < points.length; i++) {
                  ctx.lineTo(points[i].x, points[i].y);
                }
                ctx.closePath();
              }}
            >
              <Image
                x={-HEX_SIZE}
                y={-HEX_SIZE}
                width={HEX_SIZE * 2}
                height={HEX_SIZE * 2}
                image={images[hex.terrain]}
                onClick={() => handleClick(hex)}
                onMouseOver={e => {
                  e.target.getStage().container().style.cursor = 'pointer';
                  e.target.fill('#0d0e0d19'); // Assombrir au survol
                }}
                onMouseOut={e => {
                  e.target.getStage().container().style.cursor = 'default';
                  e.target.fill('#ffffff'); // Retour à la couleur normale
                }}

              />
              {reachableTiles.some(t => t.q === hex.q && t.r === hex.r) && (
                <RegularPolygon
                  sides={6}
                onClick={() => handleClick(hex)}
                  radius={HEX_SIZE * 0.9}
                  fill="rgba(0, 128, 255, 0.3)"
                />
              )}
            </Group>

            );
          })}
          {userUnits.map((unit) => {
            const { x, y } = axialToPixel(unit.position.q, unit.position.r, HEX_SIZE);
            return (
              <Image
                                              x={x - SPRITE_SIZE / 2}
                                              y={y - SPRITE_SIZE / 2}
                                              width={SPRITE_SIZE}
                                              height={SPRITE_SIZE}
                                              image={images[unit.type]}
                                              onClick={() => handleClick(unit.position)}
                                              stroke={unitSelected?.id===unit.id ? 'red' : null}
                                          />
            );
          })}
          {advUnits.map((unit) => {
            const { x, y } = axialToPixel(unit.position.q, unit.position.r, HEX_SIZE);
            return (
               <Image
                                              x={x - SPRITE_SIZE / 2}
                                              y={y - SPRITE_SIZE / 2}
                                              width={SPRITE_SIZE}
                                              height={SPRITE_SIZE}
                                              image={images[unit.type]}
                                              onClick={() => handleClick(unit.position)}
                                              stroke={unitSelected?.id===unit.id ? 'red' : null}
                                          />
            );
          })}
            {explosionEffect && (
                              <Image
                                  x={explosionEffect.x - 20}
                                  y={explosionEffect.y - 20}
                                  width={SPRITE_SIZE}
                                  height={SPRITE_SIZE}
                                  image={images['explosion']}
                              />
                          )}
        </Layer>
      </Stage>
    </div>
  );
};

export default HexBoard;