import { Button, Card, Paper, Typography } from "@mui/material";
import { useWG } from "../WarGameContext";



export const WGSelectionPanel = ({ title }) => {
    const {unitSelected, tileSelected, reset} = useWG();
    return  <Paper sx={{ padding: 2, height: '100%' }}>
    <Typography variant="h6" gutterBottom>
      Panneau de Selection
    </Typography>
    <Button variant="contained" color="primary" onClick={reset} >
        reset
    </Button>
    {tileSelected && <Card sx={{marginTop:2, padding:1}}>
        <Typography variant="body2">Tile Q: {tileSelected?.q}</Typography>
        <Typography variant="body2">Tile R: {tileSelected?.r}</Typography>
        <Typography variant="body2">Type de terrain: {tileSelected?.terrain}</Typography>
    </Card>}
    {unitSelected && <Card sx={{marginTop:2, padding:1}}>
        <Typography variant="h6">Unité sélectionnée:</Typography>
        <Typography variant="body2">Type: {unitSelected.type}</Typography>
        <Typography variant="body2">Nom: {unitSelected.name}</Typography>
        <Typography variant="body2">Points de vie: {unitSelected.defense - unitSelected.damagePoints}</Typography>
    </Card>}
    </Paper>
}